/// Brand logos rendered as single filled paths.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BrandLogo {
    Claude,
    OpenAI,
    Gemini,
    Copilot,
    Antigravity,
    Grok,
}

impl BrandLogo {
    fn path(self) -> &'static str {
        match self {
            BrandLogo::Claude => CLAUDE_D,
            BrandLogo::OpenAI => OPENAI_D,
            BrandLogo::Gemini => GEMINI_D,
            BrandLogo::Copilot => COPILOT_D,
            BrandLogo::Antigravity => ANTIGRAVITY_D,
            BrandLogo::Grok => GROK_D,
        }
    }

    fn viewbox(self) -> f32 {
        match self {
            BrandLogo::Claude => 64.0,
            BrandLogo::OpenAI => 64.0,
            BrandLogo::Gemini => 65.0,
            // Copilot's viewBox is `-14 -14 126 124`, i.e. 126 wide
            // anchored at (-14, -14). `fill_svg_path` scales from
            // (0,0); to keep the glyph centred we apply the offset
            // via a translate in `paint_brand_logo` below.
            BrandLogo::Copilot => 126.0,
            BrandLogo::Antigravity | BrandLogo::Grok => 24.0,
        }
    }
}

/// Draw a brand logo into a `size × size` square at `top_left`.
/// Backends without `fill_svg_path` (default trait impl) become
/// a no-op — the agent card still paints the avatar background
/// rect so the layout doesn't collapse.
pub fn paint_brand_logo(
    backend: &mut dyn RenderBackend,
    logo: BrandLogo,
    top_left: Point2D,
    size: f32,
    color: Color,
) {
    let viewbox = logo.viewbox();
    match logo {
        BrandLogo::Copilot => {
            // Source viewBox is `-14 -14 126 124`: shift by 14
            // before scaling so (-14, -14) maps to `top_left`.
            let scale = size / viewbox;
            let origin = Point2D::new(top_left.x + 14.0 * scale, top_left.y + 14.0 * scale);
            backend.fill_svg_path(logo.path(), origin, size, viewbox, color);
        }
        _ => backend.fill_svg_path(logo.path(), top_left, size, viewbox, color),
    }
}

/// Figma logo — five overlapping rounded shapes with different
/// alpha layers, sourced from `apps/web/src/components/icons/
/// figma-logo.tsx`. viewBox 0 0 38 57. Drawn as 5 separate
/// `fill_svg_path` calls so each path keeps its own opacity layer.
pub fn paint_figma_logo(
    backend: &mut dyn RenderBackend,
    top_left: Point2D,
    size: f32,
    color: Color,
) {
    const PATHS: [(&str, f32); 5] = [
        // Center circle (opacity 0.8).
        ("M19 28.5C19 23.2533 23.2533 19 28.5 19C33.7467 19 38 23.2533 38 28.5C38 33.7467 33.7467 38 28.5 38C23.2533 38 19 33.7467 19 28.5Z", 0.8),
        // Bottom-left rounded rect (0.5).
        ("M0 47.5C0 42.2533 4.25329 38 9.5 38H19V47.5C19 52.7467 14.7467 57 9.5 57C4.25329 57 0 52.7467 0 47.5Z", 0.5),
        // Top-right rounded rect (0.7).
        ("M19 0V19H28.5C33.7467 19 38 14.7467 38 9.5C38 4.25329 33.7467 0 28.5 0H19Z", 0.7),
        // Top-left rounded rect (0.9).
        ("M0 9.5C0 14.7467 4.25329 19 9.5 19H19V0H9.5C4.25329 0 0 4.25329 0 9.5Z", 0.9),
        // Middle-left rect (0.6).
        ("M0 28.5C0 33.7467 4.25329 38 9.5 38H19V19H9.5C4.25329 19 0 23.2533 0 28.5Z", 0.6),
    ];
    // Figma's source viewBox is 38 × 57; scale to fit the longest axis
    // so a `size × size` slot keeps the glyph centred.
    let scale = size / 57.0;
    let glyph_w = 38.0 * scale;
    let offset_x = (size - glyph_w) / 2.0;
    let origin = Point2D::new(top_left.x + offset_x, top_left.y);
    for (d, opacity) in PATHS.iter() {
        let c = Color {
            r: color.r,
            g: color.g,
            b: color.b,
            a: color.a * opacity,
        };
        backend.fill_svg_path(d, origin, glyph_w, 38.0, c);
    }
}

/// OpenCode terminal logo — multi-primitive (round-rect frame +
/// title-bar line + 3 dots + chevron + cursor line). Renders as
/// stroke art in `color`. `size` is the side length; the source
/// viewBox is 64×64.
pub fn paint_opencode_logo(
    backend: &mut dyn RenderBackend,
    top_left: Point2D,
    size: f32,
    color: Color,
) {
    let s = size / 64.0;
    let x = top_left.x;
    let y = top_left.y;
    let stroke_w = 2.5 * s;
    let dot_r = 1.5 * s;
    // Frame: rect(12,14, 40×36, rx=4) — stroked.
    let frame = Rect {
        origin: Point2D::new(x + 12.0 * s, y + 14.0 * s),
        size: Point2D::new(40.0 * s, 36.0 * s),
    };
    backend.stroke_round_rect(frame, 4.0 * s, color, stroke_w);
    // Title-bar separator: line (12,22) → (52,22).
    backend.stroke_line(
        Point2D::new(x + 12.0 * s, y + 22.0 * s),
        Point2D::new(x + 52.0 * s, y + 22.0 * s),
        color,
        2.0 * s,
    );
    // 3 dots at (18,18) (23,18) (28,18), r=1.5.
    for cx_off in [18.0, 23.0, 28.0] {
        let dot = Rect {
            origin: Point2D::new(x + (cx_off - 1.5) * s, y + (18.0 - 1.5) * s),
            size: Point2D::new(dot_r * 2.0, dot_r * 2.0),
        };
        backend.fill_oval(dot, color);
    }
    // Chevron `> ` at (18,29)→(26,35)→(18,41).
    let p1 = Point2D::new(x + 18.0 * s, y + 29.0 * s);
    let p2 = Point2D::new(x + 26.0 * s, y + 35.0 * s);
    let p3 = Point2D::new(x + 18.0 * s, y + 41.0 * s);
    backend.stroke_line(p1, p2, color, stroke_w);
    backend.stroke_line(p2, p3, color, stroke_w);
    // Cursor line (30,40) → (44,40).
    backend.stroke_line(
        Point2D::new(x + 30.0 * s, y + 40.0 * s),
        Point2D::new(x + 44.0 * s, y + 40.0 * s),
        color,
        stroke_w,
    );
}

