mod tests {
    use super::*;

    #[test]
    fn supplied_cli_brand_marks_keep_their_24px_viewbox() {
        assert_eq!(BrandLogo::Antigravity.viewbox(), 24.0);
        assert_eq!(BrandLogo::Grok.viewbox(), 24.0);
        assert_eq!(BrandLogo::Antigravity.path(), ANTIGRAVITY_D);
        assert_eq!(BrandLogo::Grok.path(), GROK_D);
    }
}
